// Verify the HMAC signature from Kirana Shop AI, then pass the action on.
// Requires NODE_FUNCTION_ALLOW_BUILTIN=crypto and KIRANA_WEBHOOK_SECRET in n8n's environment.
const crypto = require('crypto');
const item = $input.first().json;
const raw = JSON.stringify(item.body);
const expected = crypto.createHmac('sha256', $env.KIRANA_WEBHOOK_SECRET || '').update(raw).digest('hex');
if (item.headers['x-kirana-signature'] !== expected) throw new Error('Bad signature');
return [{ json: item.body }];
